import settings from "../config/settings.json" with { type: "json" };

// Split totalCents between payers in proportion to their weights (SPEC.md).
// Shares are floored; remainder cents go one at a time in payer order,
// starting with the first payer (SPEC.md rule 3).
export function settle(totalCents, weights) {
  if (!Number.isInteger(totalCents)) throw new TypeError(`amounts are integer ${settings.currency} cents`);
  const sum = weights.reduce((a, b) => a + b, 0);
  const shares = weights.map((w) => Math.floor((totalCents * w) / sum));
  let remainder = totalCents - shares.reduce((a, b) => a + b, 0);
  let i = 0;
  while (remainder > 0) {
    shares[i % shares.length] += 1;
    remainder -= 1;
    i += 1;
  }
  return shares;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { settle } from "../src/settle.js";

test("shares add up to the total", () => {
  const shares = settle(1000, [1, 1, 1]);
  assert.equal(shares.reduce((a, b) => a + b, 0), 1000);
});

// SPEC.md rule 3: remainder cents are handed out in payer order,
// starting with the first payer.
test("remainder goes to the first payers", () => {
  assert.deepEqual(settle(1000, [1, 1, 1]), [334, 333, 333]);
});

